package com.yuegang.zhihui.inventory.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.inventory.api.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.annotation.*;
public class InventoryReturnService{private final JdbcTemplate jdbc;private final InventoryService inventory;public InventoryReturnService(DataSource d,InventoryService i){jdbc=new JdbcTemplate(d);inventory=i;}@Transactional public InventoryView returnSold(InventoryCommand c){long sku=id(c.skuId());int changed=jdbc.update("UPDATE inventory_reservation SET status='RETURNED',version=version+1 WHERE request_id=? AND sku_id=? AND status='SOLD' AND quantity=?",c.requestId(),sku,c.quantity());if(changed==0){Integer done=jdbc.queryForObject("SELECT COUNT(*) FROM inventory_reservation WHERE request_id=? AND sku_id=? AND status='RETURNED'",Integer.class,c.requestId(),sku);if(done!=null&&done>0)return inventory.get(c.skuId());throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);}if(jdbc.update("UPDATE inventory_stock SET available_quantity=available_quantity+?,sold_quantity=sold_quantity-?,version=version+1 WHERE sku_id=? AND sold_quantity>=?",c.quantity(),c.quantity(),sku,c.quantity())!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);jdbc.update("INSERT INTO inventory_ledger(id,sku_id,movement_type,available_delta,locked_delta,sold_delta,reference_type,reference_id,request_id) VALUES(?,?,'RETURN',?,0,?,?,?,?)",next(),sku,c.quantity(),-c.quantity(),c.referenceType(),c.referenceId(),c.requestId());return inventory.get(c.skuId());}private static long id(String x){try{return Long.parseLong(x);}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
